        imagePrompt: "minimal privacy dashboard with lock icons, secure browser windows, and dark UI panels",
        icon: "shield",
        theme: "dark glassmorphism",
        accentColor: "#10B981",
        layout: "split-left-text-right-image"
      },
      {
        slideNumber: 3,
        title: "Notebook Workflows",
        body: "Looseleaf reflects demand for flexible developer workflows.",
        imagePrompt: "futuristic notebook workspace with AI workflow diagrams, code snippets, and productivity panels",
        icon: "workflow",
