      }
    ]
  };
}

const carouselText = parsed.slides.map(slide => {
  return `Slide ${slide.slideNumber}
${slide.title}
${slide.body}

Theme: ${slide.theme}
Icon: ${slide.icon}
Layout: ${slide.layout}
Accent Color: ${slide.accentColor}
