    linkedin_carousel_json: parsed,
    linkedin_carousel_visual_json: parsed,
    linkedin_carousel_text: carouselText,

    // Safe fallback values
    finalDraft: $json.finalDraft || "",
    wasRefined: $json.wasRefined || false
  }
}];

const slides = $json.linkedin_carousel_json.slides || [];
const issues = $json.carousel_validation_issues || [];
const isValid = $json.carousel_valid;

const blocks = [
  {
    type: "header",
    text: {
      type: "plain_text",
      text: "LinkedIn Carousel Draft"
    }
  },
  {
    type: "section",
    text: {
      type: "mrkdwn",
      text: `*Carousel Valid:* ${isValid ? "Yes" : "No"}`
    }
  }
];

if (issues.length > 0) {
  blocks.push({
    type: "section",
    text: {
      type: "mrkdwn",
      text: `*Issues Found:*\n${issues.map(issue => `• ${issue}`).join("\n")}`
    }
  });

  blocks.push({
    type: "divider"
  });
}

slides.forEach(slide => {
  blocks.push({
    type: "section",
    text: {
      type: "mrkdwn",
      text: `*Slide ${slide.slideNumber}: ${slide.title}*
${slide.body}

Theme: ${slide.theme}
Icon: ${slide.icon}
Layout: ${slide.layout}
Accent Color: ${slide.accentColor}`
    }
  });

  blocks.push({
    type: "divider"
  });
});

return [{
  json: {
    text: "LinkedIn Carousel Draft",
    blocks
  }
}];

const carousel = $json.linkedin_carousel_json;

const allowedThemes = [
  "dark blue gradient",
  "black and purple neon",
  "minimal white and gray",
  "dark glassmorphism",
  "futuristic cyan glow",
  "midnight AI theme",
  "modern fintech dark"
];

const allowedLayouts = [
  "title-top text-bottom",
  "split-left-text-right-image",
  "centered-title-centered-body",
  "title-top-icon-center",
  "full-background-image-overlay-text",
  "title-left-body-right"
];

const hexRegex = /^#([0-9A-F]{3}){1,2}$/i;

let issues = [];

if (!carousel?.slides || carousel.slides.length !== 6) {
  issues.push("Carousel does not contain exactly 6 slides.");
}

carousel?.slides?.forEach((slide, index) => {
  if (!slide.title?.trim()) {
    issues.push(`Slide ${index + 1} is missing a title.`);
  }

  if (!slide.body?.trim()) {
    issues.push(`Slide ${index + 1} is missing a body.`);
  }

  if (!slide.imagePrompt?.trim()) {
    issues.push(`Slide ${index + 1} is missing imagePrompt.`);
  }

  if (!slide.icon?.trim()) {
    issues.push(`Slide ${index + 1} is missing icon.`);
  }

  if (!slide.theme?.trim()) {
    issues.push(`Slide ${index + 1} is missing theme.`);
  }

  if (!slide.accentColor?.trim()) {
    issues.push(`Slide ${index + 1} is missing accentColor.`);
  }

  if (!slide.layout?.trim()) {
    issues.push(`Slide ${index + 1} is missing layout.`);
  }

  if (slide.theme && !allowedThemes.includes(slide.theme)) {
    issues.push(`Slide ${index + 1} has invalid theme: ${slide.theme}`);
  }

  if (slide.layout && !allowedLayouts.includes(slide.layout)) {
    issues.push(`Slide ${index + 1} has invalid layout: ${slide.layout}`);
  }

  if (slide.accentColor && !hexRegex.test(slide.accentColor)) {
    issues.push(`Slide ${index + 1} has invalid accentColor: ${slide.accentColor}`);
  }

  const wordCount = slide.body.split(/\s+/).length;

  if (wordCount > 30) {
    issues.push(`Slide ${index + 1} body exceeds 30 words.`);
  }
});

return [{
  json: {
    ...$json,
    carousel_validation_issues: issues,
    carousel_valid: issues.length === 0
  }
}];
